│   ├── entities/       # 游戏实体（玩家、陨石、粒子）
│   │   ├── Player.js
│   │   ├── Meteor.js
│   │   └── ParticleSystem.js
│   ├── systems/        # 子系统（音频、碰撞、得分）
│   │   ├── AudioManager.js
│   │   ├── CollisionSystem.js
│   │   └── ScoreSystem.js
