---

#### 二、技术栈选型（企业级标准）

| 层面 | 技术 | 理由 |
|------|------|------|
| 语言 | **TypeScript** | 类型安全，适合大型项目 |
| 构建 | **Vite + Webpack** | 快速HMR，生产优化 |
| 测试 | **Jest + Playwright** | 单元测试 + E2E |
| 代码规范 | **ESLint + Prettier + Husky** | 自动检查，提交前拦截 |
| CI/CD | **GitHub Actions** | 自动构建、测试、部署 |
| 性能 | **Canvas 2D + Web Audio API** | 60FPS保证 |
| 状态管理 | **Zustand**（轻量） | 比Redux简单，适合游戏状态 |

---

#### 三、核心代码示例（关键部分）

##### 1. 游戏循环（固定时间步长，避免帧率波动）

```typescript
// src/core/GameLoop.ts
export class GameLoop {
  private lastTime = 0;
  private accumulator = 0;
  private readonly step = 1000 / 60; // 60 FPS固定步长

  constructor(
    private update: (delta: number) => void,
    private render: () => void
  ) {}

  start() {
    this.lastTime = performance.now();
    requestAnimationFrame(this.tick.bind(this));
  }

  private tick(currentTime: number) {
    const delta = currentTime - this.lastTime;
    this.lastTime = currentTime;
    this.accumulator += delta;

    while (this.accumulator >= this.step) {
      this.update(this.step / 1000);
      this.accumulator -= this.step;
    }
    this.render();
    requestAnimationFrame(this.tick.bind(this));
  }
}
```

##### 2. 音频节拍同步（Web Audio API）

```typescript
// src/systems/AudioManager.ts
export class AudioManager {
  private audioContext: AudioContext;
  private beatInterval = 500; // 每0.5秒一个节拍（120BPM）

  constructor() {
    this.audioContext = new AudioContext();
  }

  // 生成节拍脉冲
  scheduleBeat() {
    const osc = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();
    osc.connect(gain);
    gain.connect(this.audioContext.destination);
    osc.frequency.value = 880; // A5音
    gain.gain.setValueAtTime(0.8, this.audioContext.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.1);
    osc.start();
    osc.stop(this.audioContext.currentTime + 0.1);
  }

  // 动态检测节拍（简化版，实际可用音频分析）
  getBeatPhase() {
    return (performance.now() % this.beatInterval) / this.beatInterval;
  }
}
```

##### 3. 碰撞检测（空间哈希优化）

```typescript
// src/systems/CollisionSystem.ts
export class CollisionSystem {
  private grid: Map<string, Entity[]> = new Map();
  private cellSize = 50;

  // 空间哈希，减少碰撞检测复杂度
  update(entities: Entity[]) {
    this.grid.clear();
    for (const entity of entities) {
      const key = this.getCellKey(entity.x, entity.y);
      if (!this.grid.has(key)) this.grid.set(key, []);
      this.grid.get(key)!.push(entity);
    }
  }

  checkCollisions(player: Player, meteors: Meteor[]): Meteor[] {
    const nearby = this.getNearbyEntities(player);
    return nearby.filter(m => m.intersects(player));
  }

  private getCellKey(x: number, y: number) {
    return `${Math.floor(x / this.cellSize)},${Math.floor(y / this.cellSize)}`;
  }

  private getNearbyEntities(entity: Entity): Entity[] {
    const result: Entity[] = [];
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const key = this.getCellKey(entity.x + dx * this.cellSize, entity.y + dy * this.cellSize);
        if (this.grid.has(key)) result.push(...this.grid.get(key)!);
      }
    }
    return result;
  }
}
```

