<script>
// ============================================
// 企业级架构：模块化 + 事件驱动 + 状态管理
// ============================================

// ---------- 1. 事件总线（发布-订阅模式）----------
class EventBus {
    constructor() {
        this.events = {};
    }
    on(eventName, callback) {
        if (!this.events[eventName]) this.events[eventName] = [];
        this.events[eventName].push(callback);
    }
    emit(eventName, data) {
        if (this.events[eventName]) {
            this.events[eventName].forEach(cb => cb(data));
        }
    }
}

// ---------- 2. 状态管理器 ----------
class StateManager {
    constructor() {
        this.state = {
            player: { x: 0, y: 0 },
            boxes: [],
            targets: [],
            steps: 0,
            rewinds: 0,
            won: false,
            history: []  // 用于回溯
        };
        this.listeners = [];
    }
    setState(newState) {
        Object.assign(this.state, newState);
        this.listeners.forEach(l => l(this.state));
    }
    subscribe(listener) {
        this.listeners.push(listener);
    }
    // 记录历史（用于时间回溯）
    snapshot() {
        return JSON.stringify(this.state);
    }
    restore(snapshot) {
        const data = JSON.parse(snapshot);
        this.state = data;
        this.listeners.forEach(l => l(this.state));
    }
}

// ---------- 3. 游戏主类 ----------
class Game {
    constructor(canvasId) {
        this.canvas = document.getElementById(canvasId);
        this.ctx = this.canvas.getContext('2d');
        this.eventBus = new EventBus();
        this.stateManager = new StateManager();

        // 游戏配置
        this.TILE_SIZE = 60;
        this.COLS = 8;
        this.ROWS = 6;
        this.canvas.width = this.COLS * this.TILE_SIZE;
        this.canvas.height = this.ROWS * this.TILE_SIZE;

        // 输入状态
        this.keys = {};
        this.touchX = 0;
        this.touchY = 0;

        // 粒子效果
        this.particles = [];

        // 初始化
        this.init();
        this.setupEvents();
        this.gameLoop();
    }

    init() {
        // 加载关卡（企业级：从JSON加载）
        this.currentLevel = 1;
        this.loadLevel(1);

        // 订阅状态变化，更新UI
        this.stateManager.subscribe(state => {
            document.getElementById('steps').textContent = state.steps;
            document.getElementById('rewinds').textContent = state.rewinds;
            if (state.won) {
                document.getElementById('winScreen').style.display = 'flex';
                this.spawnParticles();
            }
        });
    }

    loadLevel(levelNum) {
        // 关卡数据（企业级：从JSON文件加载）
        const levels = {
            1: {
                player:
